/**
 * pdf-dieta.js - Genera PDF piano alimentare settimanale
 * Dipende da html2pdf.js (caricato via CDN nella pagina)
 */

const LOGO_B64 = '';

const GIORNI_LABEL = ['LUNEDI\u0027','MARTEDI\u0027','MERCOLEDI\u0027','GIOVEDI\u0027','VENERDI\u0027','SABATO','DOMENICA'];
const MOMENTI = ['colazione','spuntino_mattina','pranzo','spuntino_pomeriggio','cena'];
const MOMENTI_LABEL = {
  colazione:            'COLAZIONE',
  spuntino_mattina:     'SPUNTINO\nMATTINA',
  pranzo:               'PRANZO',
  spuntino_pomeriggio:  'SPUNTINO\nPOMERIGGIO',
  cena:                 'CENA',
};

const T = '#5a8260';   // verde teal
const B = '#c8d8c8';   // border
const R = '#f7faf8';   // row label bg

function tuttiUguali(piano, sett, momento) {
  const vals = [];
  for (let g = 1; g <= 7; g++) {
    const p = piano[sett]?.[g]?.[momento];
    vals.push(p ? (p.alimento_nome + '|' + Math.round(p.quantita_g)) : '');
  }
  return vals.every(v => v === vals[0]);
}

function formatPasto(pasto, aliIdx) {
  if (!pasto || !pasto.alimento_nome) return '';
  const sostituti = (pasto.sostituti_ids || []).map(id => aliIdx[id]).filter(Boolean);
  let h = '<div style="font-weight:600;font-size:7pt;line-height:1.3;">' + pasto.alimento_nome + '</div>';
  h += '<div style="font-size:6.5pt;color:#555;">' + Math.round(pasto.quantita_g) + 'g';
  if (pasto.kcal) h += ' &middot; ' + pasto.kcal + 'kcal';
  h += '</div>';
  if (pasto.note) {
    h += '<div style="font-size:6pt;color:#777;font-style:italic;margin-top:1px;">' + pasto.note + '</div>';
  }
  if (sostituti.length) {
    h += '<div style="margin-top:3px;border-top:1px dashed ' + B + ';padding-top:2px;">';
    sostituti.forEach(function(alt) {
      var qIso = alt.energia_kcal ? Math.round((pasto.kcal || 0) / (alt.energia_kcal / 100)) : Math.round(pasto.quantita_g);
      h += '<div style="font-size:5.5pt;color:#777;">&harr; ' + alt.nome + ' ' + qIso + 'g</div>';
    });
    h += '</div>';
  }
  return h;
}

function cell(content, opts) {
  opts = opts || {};
  var style = [
    'border:1px solid ' + B,
    'padding:3px 4px',
    'vertical-align:top',
    'font-size:7pt',
    opts.bg ? 'background:' + opts.bg : '',
    opts.center ? 'text-align:center' : '',
    opts.bold ? 'font-weight:700' : '',
    opts.color ? 'color:' + opts.color : '',
    opts.colspan ? '' : 'width:12%',
  ].filter(Boolean).join(';');
  var extra = opts.colspan ? ' colspan="' + opts.colspan + '"' : '';
  return '<td' + extra + ' style="' + style + '">' + (content || '&nbsp;') + '</td>';
}

function labelCell(label) {
  return '<td style="background:' + R + ';border:1px solid ' + B + ';padding:3px 2px;width:8%;text-align:center;vertical-align:middle;">' +
    '<div style="font-size:6pt;font-weight:800;color:' + T + ';letter-spacing:.06em;white-space:pre-line;">' + label + '</div>' +
    '</td>';
}

function buildPage(piano, sett, dieta, paziente, aliIdx) {
  // Calcola totali
  var totKcal = {};
  var totProt = {}, totCarb = {}, totLip = {};
  for (var g = 1; g <= 7; g++) {
    var k = 0, p = 0, c = 0, l = 0;
    MOMENTI.forEach(function(m) {
      var ps = piano[sett] && piano[sett][g] && piano[sett][g][m];
      if (ps) { k += ps.kcal || 0; p += ps.prot || 0; c += ps.carb || 0; l += ps.lip || 0; }
    });
    totKcal[g] = Math.round(k);
    totProt[g] = Math.round(p * 10) / 10;
    totCarb[g] = Math.round(c * 10) / 10;
    totLip[g] = Math.round(l * 10) / 10;
  }

  // Header
  var logoHtml = '<img src="data:image/jpeg;base64,' + LOGO_B64 + '" style="height:50px;display:block;margin:0 auto;" />';
  var header = '<div style="display:flex;align-items:center;border-bottom:2.5px solid ' + T + ';padding-bottom:8px;margin-bottom:8px;">' +
    '<div style="width:80px;flex-shrink:0;">' + logoHtml + '<div style="font-size:6pt;color:#777;text-align:center;letter-spacing:.03em;">BIOLOGA NUTRIZIONISTA</div></div>' +
    '<div style="flex:1;padding-left:12px;">' +
    '<div style="font-size:11pt;font-weight:700;color:' + T + ';">' + dieta.nome + '</div>' +
    '<div style="font-size:7.5pt;color:#555;margin-top:2px;">Paziente: <strong>' + paziente.cognome + ' ' + paziente.nome + '</strong>' +
    '&nbsp;&middot;&nbsp;Target: <strong>' + Math.round(dieta.target_kcal) + ' kcal/giorno</strong>' +
    '&nbsp;&middot;&nbsp;Settimana ' + sett + ' di ' + dieta.numero_settimane + '</div>' +
    '<div style="font-size:6.5pt;color:#888;margin-top:2px;font-style:italic;">Le grammature riportate sono da crudo (eccetto legumi in scatola) ed al netto degli scarti</div>' +
    '</div></div>';

  // Tabella
  var colW = '12%';
  var tHead = '<thead><tr><th style="background:' + R + ';border:1px solid ' + B + ';width:8%;"></th>' +
    GIORNI_LABEL.map(function(g) {
      return '<th style="background:' + T + ';color:white;border:1px solid ' + B + ';font-size:7pt;font-weight:700;text-align:center;padding:4px 2px;width:' + colW + ';">' + g + '</th>';
    }).join('') + '</tr></thead>';

  var tBody = '<tbody>';

  MOMENTI.forEach(function(momento) {
    var label = MOMENTI_LABEL[momento];
    var isSpunt = momento === 'spuntino_mattina' || momento === 'spuntino_pomeriggio';

    if (isSpunt && tuttiUguali(piano, sett, momento)) {
      // Riquadro unico
      var primoP = piano[sett] && piano[sett][1] && piano[sett][1][momento];
      var contenuto = formatPasto(primoP, aliIdx) ||
        '<span style="color:#bbb;font-size:6pt;">Non specificato</span>';
      tBody += '<tr>' + labelCell(label) +
        '<td colspan="7" style="border:1px solid ' + B + ';padding:4px 8px;background:#fafcfa;vertical-align:middle;">' +
        contenuto + '</td></tr>';
    } else {
      tBody += '<tr>' + labelCell(label);
      for (var g = 1; g <= 7; g++) {
        var p = piano[sett] && piano[sett][g] && piano[sett][g][momento];
        var contenuto = p ? formatPasto(p, aliIdx) : '<div style="color:#ddd;text-align:center;font-size:8pt;">-</div>';
        tBody += '<td style="border:1px solid ' + B + ';padding:3px 4px;vertical-align:top;min-height:60px;">' + contenuto + '</td>';
      }
      tBody += '</tr>';
    }
  });

  // Riga totali
  tBody += '<tr><td style="background:' + T + ';color:white;border:1px solid ' + B + ';font-size:6pt;font-weight:700;text-align:center;padding:2px;">TOTALE</td>';
  for (var g = 1; g <= 7; g++) {
    var k = totKcal[g];
    var cls = k > dieta.target_kcal * 1.05 ? '#c53030' : k > dieta.target_kcal * 0.88 ? 'white' : '#ffd700';
    tBody += '<td style="background:' + T + ';color:' + cls + ';border:1px solid ' + B + ';font-size:6.5pt;font-weight:700;text-align:center;padding:2px;">' +
      (k > 0 ? k + ' kcal' : '') + '</td>';
  }
  tBody += '</tr></tbody>';

  var tabella = '<table style="width:100%;border-collapse:collapse;table-layout:fixed;">' + tHead + tBody + '</table>';

  // Note finali
  var noteHtml = '';
  if (dieta.linee_guida) {
    noteHtml = '<div style="margin-top:7px;padding:5px 8px;background:#fafcfa;border-left:3px solid ' + T + ';font-size:6.5pt;color:#555;">' +
      dieta.linee_guida + '</div>';
  }

  // Footer
  var footer = '<div style="margin-top:6px;display:flex;justify-content:space-between;border-top:1px solid ' + B + ';padding-top:4px;font-size:6pt;color:#aaa;">' +
    '<span>Dott.ssa Giulia Cortese &middot; Biologa Nutrizionista &middot; Tel. 320 145 9853</span>' +
    '<span>nutrizionistacortese.it</span></div>';

  return '<div class="pdf-page" style="font-family:Arial,sans-serif;width:277mm;min-height:185mm;padding:8mm;box-sizing:border-box;background:white;page-break-after:always;">' +
    header + tabella + noteHtml + footer + '</div>';
}

export async function esportaPianoPDF(dieta, paziente, piano, aliIdx) {
  if (typeof html2pdf === 'undefined') {
    alert('Libreria html2pdf non disponibile.');
    return;
  }

  var pages = '';
  for (var s = 1; s <= dieta.numero_settimane; s++) {
    pages += buildPage(piano, s, dieta, paziente, aliIdx);
  }

  // Contenitore: VISIBILE ma fuori schermo con clip (non fixed: html2canvas non lo renderizza)
  var wrap = document.createElement('div');
  wrap.style.cssText = 'position:absolute;top:-9999px;left:0;width:297mm;background:white;z-index:-1;';
  wrap.innerHTML = pages;
  document.body.appendChild(wrap);

  var nomefile = 'Piano_' + paziente.cognome + '_' + paziente.nome + '_' + dieta.nome.replace(/\s+/g,'_') + '.pdf';

  try {
    await html2pdf().set({
      margin: 0,
      filename: nomefile,
      image: { type: 'jpeg', quality: 0.95 },
      html2canvas: {
        scale: 2,
        useCORS: true,
        logging: false,
        scrollX: 0,
        scrollY: 0,
        windowWidth: 1122,  // 297mm a 96dpi
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' },
      pagebreak: { mode: 'css', before: '.pdf-page' },
    }).from(wrap).save();
  } finally {
    document.body.removeChild(wrap);
  }
}
